const crypto = require('crypto');
const fail = (statusCode, error) => [{ json: { ok: false, statusCode, error } }];
const authorization = $json.headers?.authorization ?? '';
if (!authorization.startsWith('Bearer ')) return fail(401, 'Sesión requerida.');
const secret = $env.JWT_SECRET;
if (!secret) return fail(500, 'JWT_SECRET no está configurado.');
try {
  const token = authorization.slice(7).trim();
  const [header, payloadPart, signature, extra] = token.split('.');
  if (!header || !payloadPart || !signature || extra) throw new Error();
  const expected = crypto.createHmac('sha256', secret).update(`${header}.${payloadPart}`).digest('base64url');
  const left = Buffer.from(signature);
  const right = Buffer.from(expected);
  if (left.length !== right.length || !crypto.timingSafeEqual(left, right)) throw new Error();
  const payload = JSON.parse(Buffer.from(payloadPart, 'base64url').toString('utf8'));
  if (!payload.exp || payload.exp <= Math.floor(Date.now() / 1000)) throw new Error();
  const role = String(payload.rol ?? '').toUpperCase();
  const permissions = (Array.isArray(payload.permisos) ? payload.permisos : []).map(value => String(value).toLowerCase());
  if (role !== 'ADMINISTRADOR_PARKING' && !permissions.includes('parqueadero.gestionar')) return fail(403, 'No tiene permisos para gestionar parqueadero.');
  const id = Number($json.body?.id);
  if (!Number.isInteger(id) || id <= 0) return fail(400, 'El identificador del usuario no es válido.');
  return [{ json: { ok: true, id } }];
} catch {
  return fail(401, 'La sesión es inválida o ha vencido.');
}

