WITH target AS MATERIALIZED (
  SELECT id FROM public.parqueadero_usuarios WHERE id = $1::bigint FOR UPDATE
), deleted_accesses AS (
  DELETE FROM public.parqueadero_accesos WHERE parqueadero_usuario_id IN (SELECT id FROM target) RETURNING id
), deleted_temporary_vehicles AS (
  DELETE FROM public.parqueadero_vehiculos_temporales WHERE parqueadero_usuario_id IN (SELECT id FROM target) RETURNING id
), deleted_authorizations AS (
  DELETE FROM public.parqueadero_autorizaciones WHERE parqueadero_usuario_id IN (SELECT id FROM target) RETURNING id
), deleted_payments AS (
  DELETE FROM public.parqueadero_pagos WHERE parqueadero_usuario_id IN (SELECT id FROM target) RETURNING id
), deleted_vehicles AS (
  DELETE FROM public.parqueadero_vehiculos WHERE parqueadero_usuario_id IN (SELECT id FROM target) RETURNING id
), deleted_user AS (
  DELETE FROM public.parqueadero_usuarios WHERE id IN (SELECT id FROM target) RETURNING id
)
SELECT
  EXISTS(SELECT 1 FROM deleted_user) AS success,
  (SELECT id::int FROM deleted_user) AS id,
  (SELECT count(*)::int FROM deleted_accesses) AS "deletedAccesses",
  (SELECT count(*)::int FROM deleted_temporary_vehicles) AS "deletedTemporaryVehicles",
  (SELECT count(*)::int FROM deleted_authorizations) AS "deletedAuthorizations",
  (SELECT count(*)::int FROM deleted_payments) AS "deletedPayments",
  (SELECT count(*)::int FROM deleted_vehicles) AS "deletedVehicles";
